/// One case: the language, what the case is called, the code, what must
/// appear in the token stream and what must not.
pub type Case = (
    Language,
    &'static str,
    &'static str,
    &'static [&'static str],
    &'static [&'static str],
);

/// Every case every grammar declares: what it is called, what it is,
